package com.example.rbac.gateway;
import com.example.rbac.common.JwtTokenService; import org.springframework.boot.SpringApplication; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.context.annotation.Bean; import org.springframework.data.redis.core.ReactiveStringRedisTemplate; import org.springframework.http.HttpStatus; import org.springframework.web.server.ServerWebExchange; import reactor.core.publisher.Mono; import org.springframework.cloud.gateway.filter.GlobalFilter;
@SpringBootApplication(scanBasePackages="com.example.rbac") public class GatewayApplication { public static void main(String[] args){SpringApplication.run(GatewayApplication.class,args);}
 @Bean GlobalFilter authenticationFilter(JwtTokenService jwt, ReactiveStringRedisTemplate redis){ return (exchange, chain) -> { String path=exchange.getRequest().getURI().getPath(); if(path.startsWith("/auth/")||path.equals("/actuator/health")) return chain.filter(exchange); String h=exchange.getRequest().getHeaders().getFirst("Authorization"); if(h==null||!h.startsWith("Bearer ")) return reject(exchange,HttpStatus.UNAUTHORIZED); try { var claims=jwt.parse(h.substring(7)); String jti=claims.getId(); String required = path.startsWith("/permissions") && "PUT".equals(exchange.getRequest().getMethod().name()) ? "permission:write" : path.startsWith("/permissions") ? "permission:read" : null; @SuppressWarnings("unchecked") var permissions = (java.util.List<String>) claims.get("permissions"); if(required != null && !permissions.contains(required)) return reject(exchange,HttpStatus.FORBIDDEN); return redis.hasKey("auth:black:" + jti).flatMap(blocked -> blocked ? reject(exchange,HttpStatus.UNAUTHORIZED) : chain.filter(exchange.mutate().request(exchange.getRequest().mutate().header("X-User-Id",claims.getSubject()).header("X-Username",String.valueOf(claims.get("username"))).build()).build())); } catch(Exception e){return reject(exchange,HttpStatus.UNAUTHORIZED);} }; }
 private static Mono<Void> reject(ServerWebExchange e,HttpStatus s){e.getResponse().setStatusCode(s);return e.getResponse().setComplete();}
}
